INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20402, 'គណនា \(\lim_{x\to 0}\dfrac{\sin{\left(x \right)}}{x}\) (ក្រាបនៃ \(y=\dfrac{\sin x}{x}\) ដូចក្នុងរូប)។', 'g12sc-cdbeb7c56e.svg', '["\\(+\\infty\\)", "\\(-1\\)", "\\(1\\)", "\\(0\\)"]', 2, NULL, 1, 'mcq', 'លីមីតគោលនៃអនុគមន៍ត្រីកោណមាត្រ ៖ \(\displaystyle\lim_{x\to0}\dfrac{\sin x}{x}=1\) ដោយ \(x\) ជារ៉ាដ្យង់។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20403, 'គណនា \(\lim_{x\to 0}\dfrac{e^{x} - 1}{x}\)។', NULL, '["\\(1\\)", "\\(e\\)", "\\(+\\infty\\)", "\\(0\\)"]', 0, NULL, 1, 'mcq', 'លីមីតគោលនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល ៖ \(\displaystyle\lim_{x\to0}\dfrac{e^x-1}{x}=1\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20404, 'គណនា \(\lim_{x\to 3}\dfrac{x^{2} - 9}{x - 3}\)។', NULL, '["\\(9\\)", "\\(0\\)", "\\(3\\)", "\\(6\\)"]', 3, NULL, 1, 'mcq', 'រាងមិនកំណត់ \(\tfrac00\) ៖ \(\dfrac{(x-3)(x+3)}{x-3}=x+3\) ចំពោះ \(x\ne3\) ដូច្នេះលីមីត \(=6\)។', 'លីមីតរាងមិនកំណត់', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20405, 'គេមាន \(f(x)=2x+1\) និង \(g(x)=x^2\)។ អនុគមន៍បណ្ដាក់ \((g\circ f)(x)=g[f(x)]\) ស្មើនឹងអ្វី ?', NULL, '["\\((2x+1)^2\\)", "\\(2x^2+1\\)", "\\(4x^2+1\\)", "\\(2x+1+x^2\\)"]', 0, NULL, 1, 'mcq', '\((g\circ f)(x)=g[f(x)]=g(2x+1)=(2x+1)^2\)។ អនុគមន៍ \(f\circ g\) ទើបស្មើ \(2x^2+1\)។', 'លីមីតនៃអនុគមន៍អសនិទាន និងអនុគមន៍បណ្ដាក់', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20406, 'គណនា \(\lim_{x\to -\infty}\left(3 + \dfrac{5}{x}\right)\)។', NULL, '["\\(0\\)", "\\(3\\)", "\\(8\\)", "\\(5\\)"]', 1, NULL, 1, 'mcq', '\(\dfrac5x\to0\) កាលណា \(x\to-\infty\) ដូច្នេះលីមីត \(=3+0=3\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20407, 'គណនា \(\lim_{x\to 0^{+}}\log{\left(x \right)}\)។', NULL, '["\\(1\\)", "\\(0\\)", "\\(-\\infty\\)", "\\(+\\infty\\)"]', 2, NULL, 1, 'mcq', 'ពេល \(x\to0^{+}\) តម្លៃ \(\ln x\) ចុះតូចជាអវិជ្ជមានឥតកំណត់ ៖ \(\lim_{x\to0^{+}}\ln x=-\infty\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Remember');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-9c0ac2e6d0.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20408, 'គណនា \(\lim_{x\to 1^{-}}\dfrac{1}{x - 1}\) (ក្រាបដូចក្នុងរូប)។', 'g12sc-9c0ac2e6d0.svg', '["\\(0\\)", "\\(+\\infty\\)", "\\(1\\)", "\\(-\\infty\\)"]', 3, NULL, 1, 'mcq', 'ពេល \(x\to1^{-}\) ភាគបែង \(x-1\to0^{-}\) (អវិជ្ជមានតូច) ភាគយក \(1>0\) ដូច្នេះលីមីត \(=-\infty\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20409, 'គណនា \(\lim_{x\to -\infty}\left(e^{x} + 4\right)\)។', NULL, '["\\(+\\infty\\)", "\\(4\\)", "\\(0\\)", "\\(5\\)"]', 1, NULL, 1, 'mcq', '\(e^x\to0\) កាលណា \(x\to-\infty\) ដូច្នេះលីមីត \(=0+4=4\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20410, 'គណនា \(\lim_{x\to +\infty}\dfrac{2 x + 1}{x - 1}\)។', NULL, '["\\(0\\)", "\\(2\\)", "\\(+\\infty\\)", "\\(1\\)"]', 1, NULL, 1, 'mcq', 'ចែកភាគយក និងភាគបែងនឹង \(x\) ៖ \(\dfrac{2+\frac1x}{1-\frac1x}\to\dfrac21=2\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'easy', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20411, 'គណនា \(\lim_{x\to 4}\dfrac{\sqrt{x} - 2}{x - 4}\)។', NULL, '["\\(4\\)", "\\(\\dfrac{1}{2}\\)", "\\(0\\)", "\\(\\dfrac{1}{4}\\)"]', 3, NULL, 2, 'mcq', 'គុណនឹងអនុញ្ញាតិរួម ៖ \(\dfrac{\sqrt x-2}{x-4}=\dfrac1{\sqrt x+2}\to\dfrac14\)។', 'លីមីតនៃអនុគមន៍អសនិទាន និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20412, 'គណនា \(\lim_{x\to +\infty}\dfrac{3 x^{2} - x + 5}{2 x^{2} + 7}\)។', NULL, '["\\(\\dfrac{3}{2}\\)", "\\(\\dfrac{2}{3}\\)", "\\(+\\infty\\)", "\\(3\\)"]', 0, NULL, 2, 'mcq', 'ដាក់ \(x^2\) ជាកត្តារួម ៖ \(\dfrac{3-\frac1x+\frac5{x^2}}{2+\frac7{x^2}}\to\dfrac32\)។', 'លីមីតរាងមិនកំណត់', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20413, 'គណនា \(\lim_{x\to 0}\dfrac{\sin{\left(5 x \right)}}{\sin{\left(3 x \right)}}\)។', NULL, '["\\(\\dfrac{3}{5}\\)", "\\(1\\)", "\\(15\\)", "\\(\\dfrac{5}{3}\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{\sin5x}{\sin3x}=\dfrac{\sin5x}{5x}\cdot\dfrac{3x}{\sin3x}\cdot\dfrac53\to\dfrac53\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20414, 'គណនា \(\lim_{x\to 0}\dfrac{e^{3 x} - 1}{x}\)។', NULL, '["\\(e^{3}\\)", "\\(3\\)", "\\(1\\)", "\\(0\\)"]', 1, NULL, 2, 'mcq', '\(\dfrac{e^{3x}-1}{x}=3\cdot\dfrac{e^{3x}-1}{3x}\to3\cdot1=3\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20415, 'ចំពោះតម្លៃ \(a\) ណា ទើបលីមីត \(\displaystyle\lim_{x\to2}\dfrac{x^2+ax-6}{x-2}\) ជាចំនួនថេរ ?', NULL, '["\\(a=2\\)", "\\(a=1\\)", "\\(a=3\\)", "\\(a=-1\\)"]', 1, NULL, 2, 'mcq', 'ភាគបែង \(\to0\) ដូច្នេះភាគយកត្រូវ \(\to0\) ៖ \(4+2a-6=0\) គឺ \(a=1\) ហើយ \(\dfrac{(x-2)(x+3)}{x-2}\to5\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20416, 'គណនា \(\lim_{x\to +\infty}\sqrt{\dfrac{4 x - 1}{x + 3}}\)។', NULL, '["\\(2\\)", "\\(4\\)", "\\(\\sqrt{2}\\)", "\\(+\\infty\\)"]', 0, NULL, 2, 'mcq', 'លីមីតនៃអនុគមន៍បណ្ដាក់ ៖ \(X=\dfrac{4x-1}{x+3}\to4\) ហើយ \(\sqrt X\to\sqrt4=2\)។', 'លីមីតនៃអនុគមន៍អសនិទាន និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20417, 'គណនា \(\lim_{x\to +\infty}\left(- x + \sqrt{x^{2} + 3 x}\right)\)។', NULL, '["\\(0\\)", "\\(3\\)", "\\(\\dfrac{3}{2}\\)", "\\(+\\infty\\)"]', 2, NULL, 2, 'mcq', 'រាង \(\infty-\infty\) ៖ គុណនឹងអនុញ្ញាតិរួម \(\dfrac{3x}{\sqrt{x^2+3x}+x}=\dfrac{3}{\sqrt{1+\frac3x}+1}\to\dfrac32\)។', 'លីមីតរាងមិនកំណត់', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20418, 'គណនា \(\lim_{x\to 0}\dfrac{1 - \cos{\left(x \right)}}{x^{2}}\)។', NULL, '["\\(2\\)", "\\(\\dfrac{1}{2}\\)", "\\(1\\)", "\\(0\\)"]', 1, NULL, 2, 'mcq', '\(1-\cos x=2\sin^2\tfrac x2\) ដូច្នេះ \(\dfrac{2\sin^2\frac x2}{x^2}=\dfrac12\left(\dfrac{\sin\frac x2}{\frac x2}\right)^2\to\dfrac12\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20419, 'គណនា \(\lim_{x\to 0}\dfrac{\log{\left(4 x + 1 \right)}}{x}\)។', NULL, '["\\(4\\)", "\\(0\\)", "\\(\\dfrac{1}{4}\\)", "\\(1\\)"]', 0, NULL, 2, 'mcq', '\(\dfrac{\ln(1+4x)}{x}=4\cdot\dfrac{\ln(1+4x)}{4x}\to4\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20420, 'គណនា \(\lim_{x\to -\infty}\dfrac{\sqrt{x^{2} + 1}}{x + 2}\)។', NULL, '["\\(0\\)", "\\(-\\infty\\)", "\\(1\\)", "\\(-1\\)"]', 3, NULL, 2, 'mcq', 'ពេល \(x\to-\infty\) គេមាន \(\sqrt{x^2+1}=|x|\sqrt{1+\frac1{x^2}}=-x\sqrt{\cdots}\) ដូច្នេះលីមីត \(=\dfrac{-x}{x}=-1\)។', 'លីមីតរាងមិនកំណត់', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20421, 'គណនា \(\lim_{x\to \dfrac{\pi}{2}}\dfrac{\cos{\left(x \right)}}{x - \dfrac{\pi}{2}}\)។', NULL, '["\\(0\\)", "\\(1\\)", "\\(-1\\)", "\\(+\\infty\\)"]', 2, NULL, 2, 'mcq', 'តាង \(\alpha=x-\tfrac\pi2\) ៖ \(\cos(\alpha+\tfrac\pi2)=-\sin\alpha\) ដូច្នេះ \(-\dfrac{\sin\alpha}{\alpha}\to-1\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20422, 'គណនា \(\lim_{x\to +\infty}x e^{- x}\)។', NULL, '["\\(+\\infty\\)", "\\(-\\infty\\)", "\\(0\\)", "\\(1\\)"]', 2, NULL, 2, 'mcq', '\(xe^{-x}=\dfrac{x}{e^x}\to0\) ព្រោះអិចស្ប៉ូណង់ស្យែលធំលឿនជាងស្វ័យគុណ ៖ \(\dfrac{e^x}{x}\to+\infty\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20423, 'គណនា \(\lim_{x\to 1}\dfrac{x^{3} - 1}{x^{2} - 1}\)។', NULL, '["\\(0\\)", "\\(3\\)", "\\(1\\)", "\\(\\dfrac{3}{2}\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{(x-1)(x^2+x+1)}{(x-1)(x+1)}=\dfrac{x^2+x+1}{x+1}\to\dfrac32\)។', 'លីមីតរាងមិនកំណត់', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20424, 'គណនា \(\lim_{x\to 0^{+}}x \log{\left(x \right)}\)។', NULL, '["\\(1\\)", "\\(-1\\)", "\\(0\\)", "\\(-\\infty\\)"]', 2, NULL, 2, 'mcq', 'តាង \(x=\tfrac1X\) ៖ \(x\ln x=-\dfrac{\ln X}{X}\to0\) កាលណា \(X\to+\infty\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20425, 'គណនា \(\lim_{x\to 0}\dfrac{e^{2 x} - e^{- x}}{x}\)។', NULL, '["\\(1\\)", "\\(2\\)", "\\(3\\)", "\\(0\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{e^{2x}-1}{x}+\dfrac{1-e^{-x}}{x}\to2+1=3\) ព្រោះ \(\dfrac{1-e^{-x}}{x}=\dfrac{e^{-x}-1}{-x}\to1\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'hard', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20426, 'គណនា \(\lim_{x\to +\infty}\left(- \sqrt{x^{2} - 2 x} + \sqrt{x^{2} + 4 x + 1}\right)\)។', NULL, '["\\(6\\)", "\\(3\\)", "\\(1\\)", "\\(\\dfrac{3}{2}\\)"]', 1, NULL, 3, 'mcq', 'ផលដក ៖ \(\dfrac{6x+1}{\sqrt{x^2+4x+1}+\sqrt{x^2-2x}}=\dfrac{6+\frac1x}{\sqrt{1+\frac4x+\cdots}+\sqrt{1-\frac2x}}\to\dfrac62=3\)។', 'លីមីតរាងមិនកំណត់', 'hard', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20427, 'គណនា \(\lim_{x\to 0}\dfrac{- \sqrt{1 - x} + \sqrt{x + 1}}{\sin{\left(3 x \right)}}\)។', NULL, '["\\(3\\)", "\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{2}{3}\\)", "\\(\\dfrac{1}{6}\\)"]', 1, NULL, 3, 'mcq', 'គុណអនុញ្ញាតិរួម ៖ \(\dfrac{2x}{(\sqrt{1+x}+\sqrt{1-x})\sin3x}=\dfrac{2}{3\cdot\frac{\sin3x}{3x}(\sqrt{1+x}+\sqrt{1-x})}\to\dfrac{2}{3\cdot2}=\dfrac13\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'hard', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20428, 'ទំនាក់ទំនងមួយណាខាងក្រោមត្រឹមត្រូវ ?', NULL, '["\\(\\displaystyle\\lim_{x\\to0^-}\\dfrac{x}{|x|}=-1\\)", "\\(\\displaystyle\\lim_{x\\to0}\\dfrac{\\sin2x}{x}=1\\)", "\\(\\displaystyle\\lim_{x\\to0}\\dfrac{e^x-1}{x}=0\\)", "\\(\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{\\ln x}{x}=+\\infty\\)"]', 0, NULL, 3, 'mcq', 'ចំពោះ \(x<0\) ៖ \(|x|=-x\) ដូច្នេះ \(\dfrac x{|x|}=-1\)។ ឯខ្សែផ្សេងទៀតខុស ៖ \(\dfrac{\sin2x}x\to2\), \(\dfrac{\ln x}x\to0\), \(\dfrac{e^x-1}x\to1\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'hard', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20429, 'គណនា \(\lim_{x\to +\infty}\left(- x^{3} + e^{x}\right)\)។', NULL, '["\\(+\\infty\\)", "\\(0\\)", "\\(1\\)", "\\(-\\infty\\)"]', 0, NULL, 3, 'mcq', '\(e^x-x^3=x^3\left(\dfrac{e^x}{x^3}-1\right)\) ដោយ \(\dfrac{e^x}{x^3}\to+\infty\) ដូច្នេះលីមីត \(=+\infty\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'hard', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20430, 'គណនា \(\lim_{x\to 1}\dfrac{x^{10} - 1}{x^{4} - 1}\)។', NULL, '["\\(\\dfrac{2}{5}\\)", "\\(6\\)", "\\(1\\)", "\\(\\dfrac{5}{2}\\)"]', 3, NULL, 3, 'mcq', 'ប្រើ \(\displaystyle\lim_{x\to1}\dfrac{x^m-1}{x^n-1}=\dfrac mn\) ដែល \(m=10,\ n=4\) ៖ \(\dfrac{10}4=\dfrac52\)។', 'លីមីតរាងមិនកំណត់', 'hard', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20431, 'គណនា \(\lim_{x\to 0}\dfrac{1 - \cos{\left(4 x \right)}}{x \sin{\left(x \right)}}\)។', NULL, '["\\(4\\)", "\\(2\\)", "\\(8\\)", "\\(16\\)"]', 2, NULL, 3, 'mcq', '\(1-\cos4x=2\sin^22x\) ៖ \(\dfrac{2\sin^22x}{x\sin x}=2\left(\dfrac{\sin2x}{2x}\right)^2\cdot\dfrac{4x^2}{x\sin x}\to2\cdot4=8\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'hard', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-1cc594c372.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20432, 'កាហ្វេក្តៅមួយកែវដាក់ក្នុងបន្ទប់ ។ សីតុណ្ហភាព (°C) ក្រោយ \(t\) នាទី គឺ \(T(t)=25+60e^{-t/10}\) ដូចក្នុងរូប ។ តើសីតុណ្ហភាពកាហ្វេខិតទៅរកតម្លៃប៉ុន្មាន (គិតជា °C) កាលណា \(t\) ធំឥតកំណត់ ?', 'g12sc-1cc594c372.svg', '["\\(60\\)", "\\(85\\)", "\\(0\\)", "\\(25\\)"]', 3, NULL, 3, 'mcq', '\(e^{-t/10}\to0\) ដូច្នេះ \(T\to25+0=25\) °C (សីតុណ្ហភាពបន្ទប់) ដែលក្រាបមាន \(y=25\) ជាអាស៊ីមតូតដេក។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-c9420b9810.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20433, 'តារាងតម្លៃតាក់ស៊ី \(F(x)\) (ដុល្លារ) តាមចម្ងាយ \(x\) (គីឡូម៉ែត្រ) ត្រូវបានបង្ហាញដោយក្រាបក្នុងរូប ។ គណនា \(\displaystyle\lim_{x\to6^{+}}F(x)-\lim_{x\to6^{-}}F(x)\) ។', 'g12sc-c9420b9810.svg', '["\\(3\\)", "\\(0\\)", "\\(11\\)", "\\(8\\)"]', 0, NULL, 3, 'mcq', 'ពីក្រាប ៖ \(\lim_{x\to6^-}F(x)=8\) (ជណ្ដើរមុន) និង \(\lim_{x\to6^+}F(x)=11\) (ជណ្ដើរបន្ទាប់) ដូច្នេះផលដក \(11-8=3\) ហើយលីមីតនៅ \(x=6\) មិនមាន (លោត \(3\) ដុល្លារ)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'pisa', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-4aafb1e6fa.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20434, 'ក្នុងរង្វង់កាំ \(1\) ធ្នូ \(AB\) ប្រវែង \(s=\theta\) ហើយអង្កត់ធ្នូ \(AB=c=2\sin\dfrac\theta2\) ដូចក្នុងរូប ។ តើសមាមាត្រ \(\dfrac cs\) ខិតទៅរកអ្វី កាលណា \(\theta\to0\) ?', 'g12sc-4aafb1e6fa.svg', '["\\(\\dfrac12\\)", "\\(2\\)", "\\(0\\)", "\\(1\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac cs=\dfrac{2\sin\frac\theta2}{\theta}=\dfrac{\sin\frac\theta2}{\frac\theta2}\to1\) ដូច្នេះ \(c\approx s\) កាលណាមុំតូច។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'pisa', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-0a7b64e123.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20435, 'ក្បួនដោះស្រាយមួយមានប្រសិទ្ធភាព \(E(n)=\dfrac{\ln n}{n}\) ដែល \(n\) ជាចំនួនទិន្នន័យ ដូចក្នុងរូប ។ តើប្រសិទ្ធភាពខិតទៅរកអ្វី កាលណា \(n\to+\infty\) ?', 'g12sc-0a7b64e123.svg', '["\\(1\\)", "\\(+\\infty\\)", "\\(0\\)", "\\(\\dfrac1e\\)"]', 2, NULL, 3, 'mcq', '\(\displaystyle\lim_{n\to+\infty}\dfrac{\ln n}{n}=0\) ព្រោះ \(\ln n\) កើនយឺតជាង \(n\)។ តម្លៃធំបំផុត \(\dfrac1e\approx0{,}37\) ត្រង់ \(n=e\) មិនមែនជាលីមីតទេ។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-9e42055127.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20436, 'ពហុកោណនិយ័ត \(n\) ជ្រុងចារឹកក្នុងរង្វង់កាំ \(1\) (រូបបង្ហាញ \(n=6\)) មានបរិមាត្រ \(P_n=2n\sin\dfrac\pi n\) ។ តើ \(P_n\) ខិតទៅរកអ្វី កាលណា \(n\to+\infty\) ?', 'g12sc-9e42055127.svg', '["\\(\\pi\\)", "\\(2\\pi\\)", "\\(2\\)", "\\(4\\pi\\)"]', 1, NULL, 3, 'mcq', '\(P_n=2\pi\cdot\dfrac{\sin\frac\pi n}{\frac\pi n}\to2\pi\cdot1=2\pi\) ជាបរិមាត្ររង្វង់កាំ \(1\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'pisa', 1, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20437, 'គណនាលីមីត \(\displaystyle\lim_{x\to-1}\dfrac{x^2-1}{x^2+3x+2}\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស \(x=-1\) ៖ ភាគយក \(=0\) និងភាគបែង \(=0\) ដូច្នេះមានរាងមិនកំណត់ \(\tfrac00\) (1 ពិន្ទុ)
ដាក់ជាកត្តា ៖ \(x^2-1=(x-1)(x+1)\) (1 ពិន្ទុ)
ភាគបែង ៖ \(x^2+3x+2=(x+1)(x+2)\) (1 ពិន្ទុ)
សម្រួលកត្តារួម \((x+1)\) (ព្រោះ \(x\ne-1\)) ៖ \(\dfrac{x-1}{x+2}\) (1 ពិន្ទុ)
ជំនួស \(x=-1\) ៖ \(\dfrac{-1-1}{-1+2}=-2\) ដូច្នេះលីមីត \(=-2\)។ (1 ពិន្ទុ)', 'លីមីតរាងមិនកំណត់', 'easy', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20438, 'គណនា \(\displaystyle\lim_{x\to+\infty}\left(\sqrt{x^2+x+1}-\sqrt{x^2-x}\right)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'រាងមិនកំណត់ \(+\infty-\infty\) ដូច្នេះគុណ និងចែកនឹងអនុញ្ញាតិរួម \(\sqrt{x^2+x+1}+\sqrt{x^2-x}\) (1 ពិន្ទុ)
ភាគយក ៖ \((x^2+x+1)-(x^2-x)=2x+1\) (1 ពិន្ទុ)
ដាក់ \(x\) ជាកត្តារួម ៖ \(\dfrac{x\left(2+\frac1x\right)}{x\left(\sqrt{1+\frac1x+\frac1{x^2}}+\sqrt{1-\frac1x}\right)}\) (1 ពិន្ទុ)
សម្រួល \(x\) (ព្រោះ \(x>0\)) ទុកប្រភាគ \(\dfrac{2+\frac1x}{\sqrt{1+\frac1x+\frac1{x^2}}+\sqrt{1-\frac1x}}\) (1 ពិន្ទុ)
ឱ្យ \(x\to+\infty\) ៖ \(\dfrac{2+0}{\sqrt1+\sqrt1}=1\) ដូច្នេះលីមីត \(=1\)។ (1 ពិន្ទុ)', 'លីមីតរាងមិនកំណត់', 'medium', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20439, 'គណនា \(\displaystyle\lim_{x\to0}\dfrac{1-\cos3x}{x^2}\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'រាងមិនកំណត់ \(\tfrac00\) ព្រោះ \(1-\cos0=0\) (1 ពិន្ទុ)
ប្រើ \(1-\cos\alpha=2\sin^2\tfrac\alpha2\) ៖ \(1-\cos3x=2\sin^2\tfrac{3x}2\) (1 ពិន្ទុ)
សរសេរ \(\dfrac{2\sin^2\frac{3x}2}{x^2}=2\cdot\dfrac94\left(\dfrac{\sin\frac{3x}2}{\frac{3x}2}\right)^2\) ព្រោះ \(\left(\tfrac{3x}2\right)^2=\tfrac94x^2\) (1 ពិន្ទុ)
ប្រើ \(\displaystyle\lim_{u\to0}\dfrac{\sin u}u=1\) ជាមួយ \(u=\tfrac{3x}2\to0\) (1 ពិន្ទុ)
លីមីត \(=2\cdot\dfrac94\cdot1^2=\dfrac92\)។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20440, 'កំណត់ចំនួនថេរ \(a\) និង \(b\) ដើម្បីឱ្យ \(\displaystyle\lim_{x\to1}\dfrac{x^2+ax+b}{x-1}=3\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោយភាគបែង \(x-1\to0\) ហើយលីមីតជាចំនួនកំណត់ ដូច្នេះភាគយកត្រូវ \(\to0\) ត្រង់ \(x=1\) (1 ពិន្ទុ)
លក្ខខណ្ឌ ៖ \(1+a+b=0\) គឺ \(b=-1-a\) (1 ពិន្ទុ)
ដាក់ជាកត្តា ៖ \(x^2+ax-1-a=(x-1)(x+1+a)\) (1 ពិន្ទុ)
សម្រួល ៖ \(\dfrac{x^2+ax+b}{x-1}=x+1+a\) ដូច្នេះលីមីត \(=2+a\) (1 ពិន្ទុ)
ឱ្យ \(2+a=3\) បាន \(a=1\) ហើយ \(b=-2\) ។ ផ្ទៀងផ្ទាត់ \(\dfrac{(x-1)(x+2)}{x-1}\to3\)។ (1 ពិន្ទុ)', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'medium', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20441, 'គណនា \(\displaystyle\lim_{x\to0}\dfrac{e^{5x}-e^{2x}}{\ln(1+3x)}\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាំងភាគយក និងភាគបែង \(\to0\) ដូច្នេះរាង \(\tfrac00\) ។ ចែកភាគយក និងភាគបែងនឹង \(x\) (1 ពិន្ទុ)
ភាគយក ៖ \(\dfrac{e^{5x}-e^{2x}}x=\dfrac{e^{5x}-1}x-\dfrac{e^{2x}-1}x\) (1 ពិន្ទុ)
ប្រើ \(\dfrac{e^{ax}-1}{ax}\to1\) ៖ ភាគយក \(\to5-2=3\) (1 ពិន្ទុ)
ភាគបែង ៖ \(\dfrac{\ln(1+3x)}x=3\cdot\dfrac{\ln(1+3x)}{3x}\to3\) (1 ពិន្ទុ)
ដូច្នេះលីមីត \(=\dfrac33=1\)។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-d70bf149ab.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20442, 'ក្រាបក្នុងរូបបង្ហាញអនុគមន៍ \(f(x)=\dfrac{2x+\sin x}{x+1}\) ដែលស្ថិតចន្លោះ \(g(x)=\dfrac{2x-1}{x+1}\) និង \(h(x)=\dfrac{2x+1}{x+1}\) ចំពោះ \(x\ge0\)។ ក. បង្ហាញថា \(g(x)\le f(x)\le h(x)\) ។ ខ. ដោយប្រើទ្រឹស្ដីបទកៀប រកលីមីតនៃ \(f(x)\) កាលណា \(x\to+\infty\)។', 'g12sc-d70bf149ab.svg', '[]', 0, NULL, 5, 'writing', 'ដោយ \(-1\le\sin x\le1\) ដូច្នេះ \(2x-1\le2x+\sin x\le2x+1\) (1 ពិន្ទុ)
ចែកនឹង \(x+1>0\) (មិនប្ដូរទិស) ៖ \(g(x)\le f(x)\le h(x)\) ចំពោះ \(x\ge0\) (1 ពិន្ទុ)
លីមី \(g\) ៖ \(\dfrac{2x-1}{x+1}=\dfrac{2-\frac1x}{1+\frac1x}\to2\) (1 ពិន្ទុ)
លីមី \(h\) ៖ \(\dfrac{2x+1}{x+1}=\dfrac{2+\frac1x}{1+\frac1x}\to2\) (1 ពិន្ទុ)
ទ្រឹស្ដីបទកៀប ៖ \(g\to2\) និង \(h\to2\) ដូច្នេះ \(\displaystyle\lim_{x\to+\infty}f(x)=2\) (ក្រាប \(f\) ត្រូវចងក្នុងក្រាប \(g\) និង \(h\))។ (1 ពិន្ទុ)', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'hard', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20443, 'ក. បង្ហាញថា \(\displaystyle\lim_{x\to+\infty}x\left(e^{1/x}-1\right)=1\) ដោយប្ដូរអថេរ ។ ខ. ទាញរក \(\displaystyle\lim_{x\to+\infty}x\left(e^{3/x}-1\right)\) ។ គ. ពន្យល់ថាហេតុអ្វីលីមីតនេះមិនអាចរកដោយជំនួស \(x=+\infty\) ត្រង់ៗ បាន។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(u=\dfrac1x\) ដូច្នេះ \(x\to+\infty\) គឺ \(u\to0^{+}\) (1 ពិន្ទុ)
សរសេរ \(x\left(e^{1/x}-1\right)=\dfrac{e^u-1}{u}\) (1 ពិន្ទុ)
ប្រើលីមីតគោល \(\dfrac{e^u-1}u\to1\) ដូច្នេះ ក. \(=1\) (1 ពិន្ទុ)
ខ. តាង \(v=\dfrac3x\to0\) ៖ \(x\left(e^{3/x}-1\right)=3\cdot\dfrac{e^v-1}{v}\to3\) (1 ពិន្ទុ)
គ. ជំនួសត្រង់ៗ បានរាង \(\infty\cdot0\) ជារាងមិនកំណត់ (ស្វ័យគុណ \(x\to\infty\) ប៉ុន្តែ \(e^{1/x}-1\to0\)) ដូច្នេះត្រូវប្ដូរអថេរដើម្បីឱ្យទៅជាលីមីតគោល។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'hard', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-751a0f9010.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20444, 'ដោយប្រើនិយមន័យ \(\varepsilon\)–\(\delta\) បង្ហាញថា \(\displaystyle\lim_{x\to3}(4x-5)=7\) (ក្រាបក្នុងរូបបង្ហាញចន្លោះ \(3\pm\delta\) និង \(7\pm\varepsilon\)) រួចរក \(\delta\) ធំបំផុតដែលបានពី \(\varepsilon=0{,}02\)។', 'g12sc-751a0f9010.svg', '[]', 0, NULL, 5, 'writing', 'ត្រូវការ ៖ ចំពោះគ្រប់ \(\varepsilon>0\) មាន \(\delta>0\) ដែល \(0<|x-3|<\delta\) នាំឱ្យ \(|f(x)-7|<\varepsilon\) (1 ពិន្ទុ)
គណនា ៖ \(|f(x)-7|=|4x-5-7|=|4x-12|=4|x-3|\) (1 ពិន្ទុ)
ដើម្បីឱ្យ \(4|x-3|<\varepsilon\) ត្រូវ \(|x-3|<\dfrac\varepsilon4\) (1 ពិន្ទុ)
យក \(\delta=\dfrac\varepsilon4\) ៖ \(0<|x-3|<\delta\) នាំឱ្យ \(|f(x)-7|=4|x-3|<4\delta=\varepsilon\) ដូច្នេះលីមីត \(=7\) (1 ពិន្ទុ)
ចំពោះ \(\varepsilon=0{,}02\) ៖ \(\delta=\dfrac{0{,}02}4=0{,}005\)។ (1 ពិន្ទុ)', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'hard', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20445, 'កំណត់អនុគមន៍ដឺក្រេទី ២ \(f(x)=px^2+qx+r\) (\(p\ne0\)) ដែលបំពេញលក្ខខណ្ឌទាំងពីរ ៖ \(\displaystyle\lim_{x\to+\infty}\dfrac{f(x)}{x^2-1}=2\) និង \(\displaystyle\lim_{x\to1}\dfrac{f(x)}{x^2-1}=-1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កាលណា \(x\to+\infty\) ៖ \(\dfrac{px^2+qx+r}{x^2-1}\to p\) ដូច្នេះ \(p=2\) (1 ពិន្ទុ)
ភាគបែង \(x^2-1\to0\) កាលណា \(x\to1\) ដូច្នេះត្រូវ \(f(1)=0\) គឺ \(2+q+r=0\) (1 ពិន្ទុ)
ដូច្នេះ \(f(x)=(x-1)(2x+c)\) ជាមួយចំនួនថេរ \(c\) (ព្រោះ \(f(1)=0\) និង \(p=2\)) (1 ពិន្ទុ)
សម្រួល ៖ \(\dfrac{f(x)}{x^2-1}=\dfrac{2x+c}{x+1}\) ហើយកាលណា \(x\to1\) បាន \(\dfrac{2+c}2=-1\) ដូច្នេះ \(c=-4\) (1 ពិន្ទុ)
ចម្លើយ ៖ \(f(x)=(x-1)(2x-4)=2x^2-6x+4\) ផ្ទៀងផ្ទាត់ \(\dfrac{2(x-2)}{x+1}\) \(\to2\) (កាលណា \(x\to+\infty\)) និង \(\to-1\) (កាលណា \(x\to1\))។ (1 ពិន្ទុ)', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'hard', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Create');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-77b5f243ac.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20446, 'កំហាប់ថ្នាំក្នុងឈាម (mg/L) បន្ទាប់ពីចាក់ \(t\) ម៉ោង ត្រូវបានគណនាដោយ \(C(t)=\dfrac{20t}{t+4}\) ដូចក្នុងរូប ។ ក. គណនា \(C(4)\)។ ខ. រកកំហាប់ដែលខិតជិតក្នុងរយៈពេលវែង \(\displaystyle\lim_{t\to+\infty}C(t)\)។ គ. តើក្រោយប៉ុន្មានម៉ោងទើបកំហាប់ដល់ \(90\%\) នៃតម្លៃលីមីតនេះ ?', 'g12sc-77b5f243ac.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(C(4)=\dfrac{20\cdot4}{4+4}=10\) mg/L (1 ពិន្ទុ)
ខ. ចែកភាគយក និងភាគបែងនឹង \(t\) ៖ \(C(t)=\dfrac{20}{1+\frac4t}\) (1 ពិន្ទុ)
ឱ្យ \(t\to+\infty\) ៖ \(\dfrac4t\to0\) ដូច្នេះលីមីត \(=20\) mg/L (អាស៊ីមតូតដេក \(y=20\)) (1 ពិន្ទុ)
គ. \(90\%\) នៃ \(20\) គឺ \(18\) ៖ \(\dfrac{20t}{t+4}=18\) គឺ \(20t=18t+72\) (1 ពិន្ទុ)
ដូច្នេះ \(2t=72\) បាន \(t=36\) ម៉ោង។ (1 ពិន្ទុ)', 'លីមីតរាងមិនកំណត់', 'pisa', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
