INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20447, 'កុងដង់សាទ័រមួយសាកថាមពល ដោយបន្ទុកក្នុងវា (µC) ក្រោយ \(t\) វិនាទី គឺ \(Q(t)=50\left(1-e^{-t/2}\right)\) ដូចក្នុងរូប ។ ក. រកបន្ទុកដែលខិតជិតពេល \(t\to+\infty\)។ ខ. រកពេលវេលាដែល \(Q=47{,}5\) (គឺ \(95\%\) នៃតម្លៃអតិបរមា) ។ គ. គណនាអត្រាដើម \(\displaystyle\lim_{t\to0}\dfrac{Q(t)}t\)។', 'g12sc-5507debb52.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(e^{-t/2}\to0\) ដូច្នេះ \(Q\to50(1-0)=50\) µC (1 ពិន្ទុ)
ខ. \(50\left(1-e^{-t/2}\right)=47{,}5\) គឺ \(e^{-t/2}=0{,}05\) (1 ពិន្ទុ)
យកលោការីតនេពែ ៖ \(-\dfrac t2=\ln0{,}05=-\ln20\) ដូច្នេះ \(t=2\ln20\approx5{,}99\) s (1 ពិន្ទុ)
គ. \(\dfrac{Q(t)}t=50\cdot\dfrac{1-e^{-t/2}}{t}=25\cdot\dfrac{e^{-t/2}-1}{-t/2}\) (1 ពិន្ទុ)
ប្រើ \(\dfrac{e^u-1}u\to1\) ជាមួយ \(u=-\tfrac t2\to0\) ៖ អត្រាដើម \(=25\) µC/s។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
