INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20448, 'រោងចក្រមួយមានចំណាយថេរ \(2\,000\) ដុល្លារ និងចំណាយលើអង្គមួយ \(15\) ដុល្លារ ។ ចំណាយមធ្យមក្នុងអង្គមួយនៅពេលផលិត \(x\) អង្គ គឺ \(C(x)=\dfrac{2\,000+15x}{x}\) ដូចក្នុងរូប ។ ក. គណនា \(C(100)\)។ ខ. រកលីមីត \(\displaystyle\lim_{x\to+\infty}C(x)\) ហើយបកស្រាយ។ គ. រកចំនួនអង្គតិចបំផុតដើម្បីឱ្យ \(C(x)<16\)។', 'g12sc-a69b5ac61e.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(C(100)=\dfrac{2\,000+1\,500}{100}=35\) ដុល្លារ/អង្គ (1 ពិន្ទុ)
ខ. សរសេរ \(C(x)=\dfrac{2\,000}x+15\) (1 ពិន្ទុ)
ឱ្យ \(x\to+\infty\) ៖ \(\dfrac{2\,000}x\to0\) ដូច្នេះ \(C\to15\) ដុល្លារ/អង្គ (ចំណាយផ្លាស់ប្ដូរ ដោយចំណាយថេរចែកទៅអង្គច្រើនឥតកំណត់) (1 ពិន្ទុ)
គ. \(\dfrac{2\,000}x+15<16\) គឺ \(\dfrac{2\,000}x<1\) (1 ពិន្ទុ)
ដោយ \(x>0\) ៖ \(x>2\,000\) ដូច្នេះតិចបំផុតគឺ \(2\,001\) អង្គ។ (1 ពិន្ទុ)', 'លីមីតរាងមិនកំណត់', 'pisa', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Apply');
