INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20449, 'សញ្ញាសំឡេងមួយអន់ថយតាមពេលវេលា ដោយវ៉ុលរបស់វា (V) គឺ \(V(t)=12e^{-0{,}2t}\) (t គិតជាវិនាទី) ដូចក្នុងរូប ។ ក. រក \(\displaystyle\lim_{t\to+\infty}V(t)\)។ ខ. តើពេលណាវ៉ុលនៅសល់ពាក់កណ្ដាលតម្លៃដើម ? គ. បង្ហាញថា \(\displaystyle\lim_{t\to+\infty}t^3V(t)=0\) ហើយបកស្រាយ។', 'g12sc-f354828a34.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(-0{,}2t\to-\infty\) ដូច្នេះ \(e^{-0{,}2t}\to0\) ហើយ \(V\to0\) V (1 ពិន្ទុ)
ខ. \(12e^{-0{,}2t}=6\) គឺ \(e^{-0{,}2t}=\tfrac12\) (1 ពិន្ទុ)
យកលោការីត ៖ \(-0{,}2t=-\ln2\) ដូច្នេះ \(t=5\ln2\approx3{,}47\) s (1 ពិន្ទុ)
គ. \(t^3V(t)=12t^3e^{-0{,}2t}\) តាង \(u=0{,}2t\) ៖ \(12\cdot125\,u^3e^{-u}\) (1 ពិន្ទុ)
ដោយ \(\dfrac{u^3}{e^u}\to0\) កាលណា \(u\to+\infty\) ដូច្នេះលីមី \(=0\) ៖ អិចស្ប៉ូណង់ស្យែលអន់ថយលឿនជាងស្វ័យគុណនៃ \(t\) កើន។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-ac3d77bdc3.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20450, 'ចំនួនត្រីក្នុងបឹងមួយ ក្រោយ \(t\) ឆ្នាំ ត្រូវបានគណនាដោយ \(P(t)=\dfrac{5\,000}{1+49e^{-0{,}4t}}\) ដូចក្នុងរូប ។ ក. រក \(P(0)\)។ ខ. រកលីមីត \(\displaystyle\lim_{t\to+\infty}P(t)\) (សមត្ថភាពអតិបរមា) ។ គ. តើក្រោយប៉ុន្មានឆ្នាំ ចំនួនត្រីដល់ពាក់កណ្ដាលសមត្ថភាព ? ឃ. វាយតម្លៃថាតើបឹងអាចមានត្រី \(6\,000\) ក្បាលដែរឬទេ ?', 'g12sc-ac3d77bdc3.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(P(0)=\dfrac{5\,000}{1+49}=100\) ក្បាល (1 ពិន្ទុ)
ខ. \(e^{-0{,}4t}\to0\) ដូច្នេះ \(P\to\dfrac{5\,000}{1+0}=5\,000\) ក្បាល (1 ពិន្ទុ)
គ. \(P=2\,500\) ៖ \(1+49e^{-0{,}4t}=2\) គឺ \(e^{-0{,}4t}=\dfrac1{49}\) (1 ពិន្ទុ)
ដូច្នេះ \(t=\dfrac{\ln49}{0{,}4}\approx9{,}73\) ឆ្នាំ (1 ពិន្ទុ)
ឃ. \(1+49e^{-0{,}4t}>1\) ដូច្នេះ \(P(t)<5\,000\) គ្រប់ \(t\) ហើយ \(P\to5\,000\) ដូច្នេះមិនអាចមាន \(6\,000\) ក្បាលបានទេ (អាស៊ីមតូត \(y=5\,000\))។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 0, '12SC', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 2 : លីមីត', NULL, 0, 'Evaluate');
